rna=""

def read_table(file):
    with open(file, "r") as f:
        table = {}
        for line in f:
            line = line.rstrip()
            if line == "":
                continue
            rnacodon, aa = line.split(" ") #rnacodon and its aa are single space separated in table ("_" for stop codons)
            table[rnacodon] = aa
    return table

def translate_seq(rna, init_pos=0):
    table=read_table("antibiotics_week_3/RNA_codon_table_1.txt")
    return [table[rna[pos:pos + 3]] for pos in range(init_pos, len(rna) - 2, 3)][0:-1] #don't include the last element of the list ("_") since it is a stop codon

print("".join(translate_seq(rna)))